{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Ensure every security group and rule has a description",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' is missing a description, which is a best practice for tracking and auditing purposes."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Ensure no security groups allow egress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' allows unrestricted egress, which could lead to unintended outbound traffic."
    },
    {
      "check_id": "CKV_AWS_24",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 22",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' allows unrestricted ingress to all ports, including SSH (port 22), potentially exposing instances to unauthorized access."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 3389",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' allows unrestricted ingress to all ports, including RDP (port 3389), potentially exposing instances to unauthorized access."
    },
    {
      "check_id": "CKV_AWS_260",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 80",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "Although port 80 is a common HTTP port, allowing ingress from 0.0.0.0/0 to it may not be a significant risk as it's often required for public-facing services, but it should be reviewed for necessity."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' allows unrestricted ingress to all ports and protocols, which is a significant risk as it exposes instances to potential unauthorized access on any port."
    },
    {
      "check_id": "CKV2_AWS_5",
      "title": "Ensure that Security Groups are attached to another resource",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' is not associated with any resource, making it unnecessary and potentially a leftover configuration."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name        = \"allow-http-lb\"\n  description = \"Allow HTTP ingress for load balancer\"\n  vpc_id      = data.aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n  egress {\n    from_port   = 0\n    to_port     = 0\n    protocol    = \"-1\"\n    cidr_blocks = [\"10.0.0.0/16\"] # Restrict egress to internal VPC range for example\n  }\n}\n",
  "fix_summary": "Added a description to the security group, restricted ingress to only HTTP (port 80), and limited egress to an internal IP range. The security group name was also updated to reflect its new, restricted purpose."
}
